/* ========================== Mascotes ========================== */
// Duas personagens, cada uma com o seu papel:
//   Abi (abacate)  · calmo e sábio: comida, dados, conselhos, tutorial.
//   Morango        · enérgico e curioso: água, treino, desafios, prémios.
// Vida por camadas: animação do corpo por humor (MOOD_ANIM), pálpebras que piscam por cima da imagem,
// "falar" enquanto o balão escreve, partículas de reação e um "boing" ao toque.
const MASCOTS = {
  abi:     { name:BRAND.mascot,  src:"data:image/webp;base64,",     ar:420/318, lid:"#E3E9A0", eyes:[[40.3,24.2],[66.9,23.8]], eye:[14,11] },
  morango: { name:BRAND.mascot2, src:"data:image/webp;base64,", ar:380/443, lid:"#D4473D", eyes:[[44.2,30.2],[58.6,30.6]], eye:[11.5,13.5] }
};
const MOOD_ANIM = { happy:"m-float", wave:"m-sway", wink:"m-sway", wow:"m-pop", party:"m-jump", think:"m-tilt", sleepy:"m-sleep" };
// Acessórios da roda, desenhados por cima do Abi (espaço 100 × 132 da imagem).
const ACC_SVG = {
  acc_chef:`<path d="M37 14c-8 0-9-11 0-12 2-6 12-8 16-2 4-6 15-3 15 3 9 1 8 12 0 12z" fill="#fff" stroke="#D8D3C4" stroke-width="1.5"/><rect x="38" y="11" width="30" height="7" rx="2" fill="#fff" stroke="#D8D3C4" stroke-width="1.5"/>`,
  acc_oculos:`<rect x="31" y="27" width="20" height="13" rx="6" fill="#1F2B22" opacity=".92"/><rect x="57" y="26" width="20" height="13" rx="6" fill="#1F2B22" opacity=".92"/><path d="M51 32h6" stroke="#1F2B22" stroke-width="2.4"/><path d="M35 31l6-2M61 30l6-2" stroke="#fff" stroke-width="1.5" opacity=".45"/>`,
  acc_banda:`<path d="M24 15q31-12 62 0l-1.5 6q-29.5-10-59 0z" fill="#E8664F"/><path d="M84 16l7-3-1 7z" fill="#E8664F"/>`,
  acc_cachecol:`<path d="M15 57q42 12 82 0l1 8q-42 13-84 0z" fill="#B95C40"/><path d="M78 65l5 19-8 1-3-18z" fill="#B95C40"/>`,
  acc_coroa:`<path d="M38 12l3-14 8 8 6-12 6 12 8-8 3 14z" fill="#E2B13C" stroke="#9A6A12" stroke-width="1.5" stroke-linejoin="round"/><circle cx="55" cy="4" r="2" fill="#fff"/>`
};
function mascot(who, { mood="happy", size=120, acc=null, cls="" } = {}){
  const m = MASCOTS[who] || MASCOTS.abi, h = Math.round(size * m.ar), closed = mood === "sleepy";
  const delay = (rnd() * 4).toFixed(2);
  const lids = m.eyes.map(([x, y]) => `<i class="lid${closed ? " shut" : ""}" style="left:${(x - m.eye[0]/2).toFixed(1)}%;top:${(y - m.eye[1]/2).toFixed(1)}%;width:${m.eye[0]}%;height:${m.eye[1]}%;background:${m.lid};animation-delay:${delay}s"></i>`).join("");
  return `<span class="mwrap ${MOOD_ANIM[mood] || "m-float"} ${cls}" data-who="${who}" style="width:${size}px;height:${h}px" role="img" aria-label="${esc(m.name)}">
    <span class="mbody"><img src="${m.src}" alt="" width="${size}" height="${h}" draggable="false">${lids}
    ${who === "abi" && acc && ACC_SVG[acc] ? `<svg class="macc" viewBox="0 0 100 132" aria-hidden="true">${ACC_SVG[acc]}</svg>` : ""}</span></span>`;
}
function abi({ mood="happy", size=120, acc, cls="" } = {}){ return mascot("abi", { mood, size, acc: acc === undefined ? S.equip : acc, cls }); }
function morango({ mood="happy", size=110, cls="" } = {}){ return mascot("morango", { mood, size, cls }); }
const face = (who, opts) => (who === "morango" ? morango : abi)(opts);

// Partículas de reação a sair da mascote: corações, brilhos ou gotas.
const BURST_SVG = {
  heart:`<path d="M12 20s-7-4.4-7-10a4 4 0 0 1 7-2.6A4 4 0 0 1 19 10c0 5.6-7 10-7 10z" fill="currentColor"/>`,
  spark:`<path d="M12 3c.8 4.6 2.5 6.4 7 7.4-4.5 1-6.2 2.8-7 7.4-.8-4.6-2.5-6.4-7-7.4 4.5-1 6.2-2.8 7-7.4z" fill="currentColor"/>`,
  drop:`<path d="M12 3.5s6 6.6 6 11a6 6 0 0 1-12 0c0-4.4 6-11 6-11z" fill="currentColor"/>`
};
function burst(el, kind = "spark"){
  if (!el || lowMotion()) return; const r = el.getBoundingClientRect(); if (!r.width) return;
  const col = { heart:"var(--coral)", spark:"var(--sun)", drop:"var(--water)" }[kind];
  for (let i = 0; i < 7; i++) { const p = document.createElement("span"); p.className = "burst";
    p.style.cssText = `left:${r.left + r.width/2}px;top:${r.top + r.height*.35}px;color:${col};--dx:${((rnd() - .5) * 140).toFixed(0)}px;--dy:${(-50 - rnd() * 80).toFixed(0)}px;--s:${(.6 + rnd() * .7).toFixed(2)};animation-delay:${(i * 35)}ms`;
    p.innerHTML = `<svg viewBox="0 0 24 24" width="18" height="18">${BURST_SVG[kind]}</svg>`; document.body.appendChild(p); setTimeout(() => p.remove(), 1300); }
}
document.addEventListener("click", e => { const w = e.target.closest(".mwrap"); if (!w || lowMotion()) return;
  w.classList.remove("m-boing"); void w.offsetWidth; w.classList.add("m-boing"); snd("ok"); burst(w, w.dataset.who === "morango" ? "spark" : "heart"); });

/* ========================== Balões de fala ========================== */
// Um só componente para toda a app: cor da personagem, nome, "a escrever…" e texto a aparecer letra a letra.
function bubbleHTML(who, { action, cls="" } = {}){
  const m = MASCOTS[who] || MASCOTS.abi;
  return `<div class="bub bub-${who} ${cls}"><span class="bub-name">${esc(m.name)}</span><p class="bub-t"><span class="typing"><i></i><i></i><i></i></span></p>${action ? `<button class="btn sm bub-act">${esc(action)}</button>` : ""}</div>`;
}
// Escreve o texto no balão. Enquanto escreve, a mascote "fala" (classe .talking).
function speak(root, text, { fast } = {}){
  const t = $(".bub-t", root), w = $(".mwrap", root); if (!t) return;
  if (lowMotion()) { t.textContent = text; return; }
  clearInterval(root._typer); clearTimeout(root._wait);
  if (w) w.classList.add("talking");
  root._wait = setTimeout(() => { t.textContent = ""; let i = 0;
    root._typer = setInterval(() => { t.textContent = text.slice(0, ++i); if (i >= text.length || !t.isConnected) { clearInterval(root._typer); if (w) w.classList.remove("talking"); } }, fast ? 14 : 22);
  }, fast ? 0 : 420);
}
function typeInto(el, text){ if (!el) return; if (lowMotion()) { el.textContent = text; return; } el.textContent = ""; let i = 0; const t = setInterval(() => { el.textContent = text.slice(0, ++i); if (i >= text.length || !el.isConnected) clearInterval(t); }, 18); }

/* ========================== Mascotes que falam ========================== */
// Aparecem em momentos-chave, no máximo a cada 12 s, e podem ser desligadas em Aparência.
const LINES = {
  meal:[["abi","Registado. Cada registo ajuda-te a conhecer-te melhor.","happy","heart"],["abi","Boa, já está no diário.","happy","heart"],["morango","Hmm, isso parece mesmo bom!","wink","spark"],["abi","Comer a horas faz mais diferença do que parece.","happy","heart"]],
  water:[["morango","Glu glu! Mais um copo.","party","drop"],["morango","O teu corpo agradece!","wink","drop"],["abi","Hidratação em dia. Bem feito.","happy","drop"]],
  waterGoal:[["morango","Meta da água cumprida! Estás imparável.","party","drop"]],
  workout:[["morango","Treino feito! Hoje mexeste-te a sério.","party","spark"],["morango","Que energia! Agora descansa e come bem.","party","spark"]],
  challenge:[["morango","Desafio concluído! Tens um giro à tua espera.","party","spark"]],
  fav:[["abi","Guardei nas tuas favoritas.","happy","heart"]],
  hello:[["abi","Olá de novo. Vamos com calma hoje.","wave","heart"],["morango","Bom dia! Pronto para um dia bom?","wink","spark"],["abi","Que bom ver-te. Um passo de cada vez.","happy","heart"]],
  weight:[["abi","Peso registado. O que conta é a tendência, não um dia.","happy","heart"]],
  plan:[["morango","Plano montado. Vamos a isso!","party","spark"]]
};
let lastSay = 0;
function say(kind, force){
  if (S.talk === false || !S.ob || !$("#ob").classList.contains("hide") || $("#tour")) return;
  const now = Date.now(); if (!force && now - lastSay < 12000) return;
  const L = LINES[kind]; if (!L) return; lastSay = now;
  const [who, text, mood, fx] = L[Math.floor(rnd() * L.length)];
  let el = $("#talk"); if (!el) { el = document.createElement("div"); el.id = "talk"; el.className = "talk"; document.body.appendChild(el); }
  el.innerHTML = face(who, { mood, size: who === "morango" ? 74 : 56 }) + bubbleHTML(who);
  el.classList.remove("out"); void el.offsetWidth; el.classList.add("on");
  speak(el, text, { fast:true }); setTimeout(() => burst($(".mwrap", el), fx), 250);
  clearTimeout(say.h); const hide = () => { el.classList.add("out"); setTimeout(() => el.classList.remove("on", "out"), 300); };
  say.h = setTimeout(hide, 3600 + text.length * 24); el.onclick = hide;
}
